import{_ as i,l as c,o as a,c as n,v as o,p as r,x as t,d as s,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Unix 域套接字","description":"","frontmatter":{"title":"Unix 域套接字","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/unix-socket.md","filePath":"cs/unix-socket.md","lastUpdated":1789023840000}'),_={name:"cs/unix-socket.md"};function h(m,e,A,f,u,E){const d=c("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="unix-域套接字" tabindex="-1">Unix 域套接字 <a class="header-anchor" href="#unix-域套接字" aria-label="Permalink to &quot;Unix 域套接字&quot;">​</a></h1><div class="epigraph"><p>AF_UNIX 在同一台机器上提供套接字语义：流或数据报、连接或会合，并可传递文件描述符与凭据。</p><footer>—— 据 Stevens, UNIX Network Programming；POSIX 对 AF_UNIX 的整理</footer></div><p><a href="/cs/named-pipe">上一课</a>只有单向字节流。<a href="/cs/file-bytestream">文件作为字节流</a> 与 <a href="/cs/socket-api">socket</a> 课（网络栏）会共用 fd，但网络课还没开始。缺口是<strong>本机套接字</strong>：命名可以是文件系统路径或抽象名，不必有端口与 IP。把「像管道但更富」合并进一课，不当百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FIFO 不能一次 <code>send</code> 保留消息边界，不能把已打开的 fd 交给对方，不能方便地做双向。<code>socketpair</code> 给出匿名的一对 Unix 域套接字，像双向 pipe。<code>bind</code> 到路径则像命名 FIFO，但协议是套接字：<code>listen</code>/<code>accept</code> 或 <code>SOCK_DGRAM</code>。缺口不是 TCP 握手，而是本地传输：内核把缓冲从发送方拷到接收方，可附带 <code>SCM_RIGHTS</code>（传 fd）与凭据。</p><p>本课不把每个 <code>cmsg</code> 头写成手册。</p><p><span class="marginnote">传 fd 是把打开文件表项在接收进程里再占一槽，指向同一打开文件对象。这不是复制文件内容。本课讲机制，不讲利用泄露的 fd。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>socket(AF_UNIX, SOCK_STREAM, 0)</code>，<code>bind</code>/<code>connect</code> 走 <a href="/cs/path-lookup">路径查找</a> 或抽象命名空间。数据仍是内核缓冲，不经网卡，不经 <a href="/cs/iommu">IOMMU</a>。关闭语义类似套接字：半关闭可以。权限：路径受目录模式约束；凭据让接收方看见对端 uid。</p>',9)),(a(),r(p,null,{default:t(()=>[l(d,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BF%9B%E7%A8%8B%20A%20send%22%5D%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%20Unix%20%E5%9F%9F%E7%BC%93%E5%86%B2%22%5D%0A%20%20K%20--%3E%20B%5B%22%E8%BF%9B%E7%A8%8B%20B%20recv%22%5D%0A%20%20A%20--%3E%20FD%5B%22%E5%8F%AF%E9%80%89%3A%20%E4%BC%A0%E9%80%92%20fd%22%5D%0A%20%20FD%20--%3E%20TAB%5B%22%E5%86%99%E5%85%A5%E5%AF%B9%E6%96%B9%20fd%20%E8%A1%A8%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Unix 域把网络栏将出现的套接字 API 先落在本机，让桌面总线、数据库本地连接不必绕 lo 接口。与管道对照：同一隔离（地址空间仍分开），更富的控制面。不要提前讲 TCP 拥塞。共享内存下一课会把载荷从拷贝改成映射。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>SOCK_SEQPACKET</code> 的全部保证当必考。不把 Linux 抽象命名空间的 <code>@</code> 前缀写成唯一实现。下一课：双方映射同一物理页，字节不再经内核拷贝。</p><p>后课默认：本机已有富 IPC 套接字。大块共享、需自行同步，下一课 POSIX 共享内存。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AF_UNIX 提供流/数据报与可选传 fd、凭据。</li><li>数据走内核拷贝，不经网络栈。</li><li>共享物理页是 posix-shm 的缺口。</li><li>出处：Stevens, <em>UNP</em>；POSIX AF_UNIX；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const B=i(_,[["render",h]]);export{S as __pageData,B as default};
